<?php
require '../../config/database.php'; require '../../includes/functions.php'; require_admin(); $err='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
 verify_csrf(); $action=$_POST['action']??'';
 if ($action==='create') {
  $name=trim($_POST['name']??''); $email=strtolower(trim($_POST['email']??'')); $password=$_POST['password']??''; $role=$_POST['role']??'customer';
  if(strlen($name)<2 || !filter_var($email,FILTER_VALIDATE_EMAIL) || strlen($password)<12 || strlen($password)>72 || !in_array($role,['customer','staff','admin'],true)) { flash('error','Enter a valid name, email, role, and password of at least 12 characters.'); }
  else { $st=$pdo->prepare('SELECT id FROM users WHERE email=?');$st->execute([$email]);if($st->fetch())flash('error','That email address already exists.');else{$pdo->prepare('INSERT INTO users(name,email,password,role,status) VALUES(?,?,?,?,\'active\')')->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role]);flash('success',ucfirst($role).' account created.');} }
 } elseif ($action==='update') {
  $id=(int)($_POST['id']??0); $role=$_POST['role']??''; $status=$_POST['status']??'';
  if(!in_array($role,['customer','staff','admin'],true)||!in_array($status,['active','inactive'],true))flash('error','Invalid role or account status.');
  elseif($id===(int)$_SESSION['user']['id'] && ($role!=='admin'||$status!=='active'))flash('error','You cannot remove your own administrator access.');
  else {
   $stmt=$pdo->prepare('UPDATE users SET role=?,status=? WHERE id=?');
   $stmt->execute([$role,$status,$id]);
   log_security_event($pdo, 'user_access_changed', (int)$_SESSION['user']['id'], 'Account role/status changed for user ID ' . $id);
   flash('success','User role and account status updated.');
  }
 } elseif ($action==='delete') {
  $id=(int)($_POST['id']??0);
  if($id===(int)$_SESSION['user']['id'])flash('error','You cannot delete your own account.');
  else { $st=$pdo->prepare('SELECT COUNT(*) FROM bookings WHERE user_id=?');$st->execute([$id]);if((int)$st->fetchColumn()>0){$pdo->prepare("UPDATE users SET status='inactive' WHERE id=?")->execute([$id]);
    log_security_event($pdo, 'user_deactivated', (int)$_SESSION['user']['id'], 'Account with booking history deactivated: ID ' . $id);
    flash('success','This account has booking history, so it was deactivated instead of deleted.');}else {
    $pdo->prepare('DELETE FROM users WHERE id=?')->execute([$id]);
    log_security_event($pdo, 'user_deleted', (int)$_SESSION['user']['id'], 'User account deleted: ID ' . $id);
    flash('success','User account removed.');
   } }
 }
 header('Location: '.url('admin/users/index.php'));exit;
}
$users=$pdo->query('SELECT u.*,COUNT(b.id) booking_count FROM users u LEFT JOIN bookings b ON b.user_id=u.id GROUP BY u.id ORDER BY FIELD(u.role,\'admin\',\'staff\',\'customer\'),u.created_at DESC')->fetchAll();
$counts=['customer'=>0,'staff'=>0,'admin'=>0];foreach($users as $u){$counts[$u['role']]++;}
$page_title='User Management';include '../../includes/header.php'; ?>
