<section class="panel" id="create-user"><div class="panel-heading"><div><h2>Create user account</h2><p class="muted">Public registration is always limited to the customer role.</p></div></div><form method="post" class="user-create-form" data-confirm="Create this account with the selected role? Only trusted staff should receive staff or admin access." data-confirm-title="Create user account"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="create"><div class="form-group"><label>Full name</label><input class="input" name="name" required minlength="2"></div><div class="form-group"><label>Email address</label><input class="input" type="email" name="email" required></div><div class="form-group"><label>Temporary password</label><input class="input" type="password" name="password" minlength="12" maxlength="72" required></div><div class="form-group"><label>Role</label><select class="select" name="role"><option value="customer">Customer</option><option value="staff">Receptionist / Staff</option><option value="admin">Administrator</option></select></div><button class="btn btn-primary">Create account</button></form></section>
<section class="panel staff-section"><div class="panel-heading"><div><h2>All accounts</h2><p class="muted">Role changes take effect on the user's next request.</p></div><span class="pill-count"><?=count($users)?> accounts</span></div><div class="table-wrap clean-table"><table class="table"><thead><tr><th>User</th><th>Current role</th><th>Bookings</th><th>Access</th><th>Update permissions</th><th></th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><strong><?=e($u['name'])?></strong><small class="table-sub"><?=e($u['email'])?></small></td><td><span class="role-pill role-<?=e($u['role'])?>"><?=e(ucfirst($u['role']))?></span></td><td><?=e($u['booking_count'])?></td><td><span class="badge <?=$u['status']==='active'?'confirmed':'cancelled'?>"><?=e(ucfirst($u['status']))?></span></td><td><form method="post" class="user-update-form" data-confirm="Save this account role and access status?" data-confirm-title="Update account access"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?=$u['id']?>"><select class="select" name="role" aria-label="Role for <?=e($u['name'])?>" <?=$u['id']==$_SESSION['user']['id']?'disabled':''?>><?php foreach(['customer'=>'Customer','staff'=>'Receptionist / Staff','admin'=>'Administrator'] as $val=>$label): ?><option value="<?=$val?>" <?=$u['role']===$val?'selected':''?>><?=$label?></option><?php endforeach; ?></select><select class="select" name="status" aria-label="Status for <?=e($u['name'])?>" <?=$u['id']==$_SESSION['user']['id']?'disabled':''?>><option value="active" <?=$u['status']==='active'?'selected':''?>>Active</option><option value="inactive" <?=$u['status']==='inactive'?'selected':''?>>Inactive</option></select><?php if($u['id']==$_SESSION['user']['id']): ?><span class="muted tiny">Current account</span><?php else: ?><button class="btn btn-primary btn-sm">Save</button><?php endif; ?></form></td><td><?php if($u['id']!=$_SESSION['user']['id']): ?><form method="post" data-confirm="Remove this account? Accounts with booking history will be deactivated instead." data-confirm-title="Remove account"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="btn btn-outline btn-sm">Remove</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section></section></div><?php include '../../includes/footer.php'; ?>